  'vec.title': "Colonne vectorielle sur {table}",
  'vec.intro': "Ajoute une colonne d'embedding vector(n) (n : les dimensions du fournisseur de vecteurs), un index HNSW pour la distance et un déclencheur qui recalcule l'embedding d'une ligne quand ses colonnes sources changent. Une configuration de recherche de type vector ou hybrid, ou l'outil Retrieve d'un agent IA, trouve alors les lignes par leur sens. Les lignes existantes sont mises en file d'attente tout de suite pour leurs embeddings.",
  'vec.existing': "Colonnes vectorielles actuelles",
  'vec.provider': "Fournisseur de vecteurs",
  'vec.provider_help': "Composants partagés › Fournisseurs de vecteurs des applications de cet espace de travail. Recherchez avec le même fournisseur.",
  'vec.keep': "Tenir à jour",
  'vec.keep_help': "Un fournisseur de type fonction peut définir l'embedding dans le déclencheur, tout de suite. Un service IA est appelé par le serveur : le déclencheur met la ligne en file d'attente et le serveur calcule les embeddings par lots, dans la limite des requêtes par minute du fournisseur et des limites IA quotidiennes de l'application.",
