  'st.header_title': 'Authentification par en-tête HTTP',
  'st.header_intro': 'Utilisé seulement quand l’authentification est « En-tête HTTP ». Un proxy inverse ou une passerelle d’authentification unique connecte les utilisateurs et transmet le nom d’utilisateur dans un en-tête ; pgkiln ne lui fait confiance que depuis les adresses de proxy de {env}',
  'st.header_unset': 'non défini sur ce serveur : la connexion par en-tête est refusée',
  'st.header_name': 'En-tête du nom d’utilisateur',
  'st.header_name_help': 'L’en-tête de la requête avec le nom d’utilisateur (APEX : HTTP Header Variable). Vide : X-Remote-User. Un en-tête modifié ou absent met fin à la session.',
