  'st.logout_url_ph': 'p. ex. https://sso.example.com/logout',
  'st.logout_url_help': 'Où mène « Se déconnecter » après la fin de la session, en général la page de déconnexion du proxy. Vide : une page « déconnecté ».',
  'st.header_auto': 'Créer les comptes automatiquement',
  'st.header_auto_help': 'Un nom d’utilisateur inconnu reçoit un nouveau compte avec accès à cette application. Sinon, le compte doit exister et avoir accès.',
  'st.db_title': 'Comptes de base de données',
  'st.db_intro': 'Utilisé seulement quand l’authentification est « Comptes de base de données ». Les utilisateurs se connectent avec un rôle de connexion PostgreSQL et son mot de passe, vérifiés par une courte connexion à cette base sous ce rôle. Les superutilisateurs et les rôles propres à pgkiln sont toujours refusés ; sans aucun des deux champs, personne ne peut se connecter.',
  'st.db_roles': 'Rôles autorisés',
  'st.db_roles_ph': 'p. ex. alice, bob',
  'st.db_roles_help': 'Rôles de connexion autorisés à se connecter, séparés par des virgules (noms exacts).',
  'st.db_member': 'Ou membres du rôle',
  'st.db_member_ph': 'p. ex. app_users_group',
  'st.db_member_help': 'Tout membre de ce rôle peut aussi se connecter.',
  'st.custom_title': 'Authentification personnalisée',
  'st.custom_intro': 'Utilisé seulement quand l’authentification est « Personnalisée ». Votre propre PL/pgSQL vérifie le nom d’utilisateur et le mot de passe du formulaire, sous le rôle de base de données de l’application ; le mot de passe est passé en paramètre et jamais journalisé. Les échecs sont freinés comme les autres connexions. Sans aucun des deux champs, personne ne peut se connecter.',
  'st.custom_fn': 'Nom de la fonction',
  'st.custom_fn_ph': 'p. ex. app.check_login',
  'st.custom_fn_help': 'Une fonction (p_username text, p_password text) returns boolean, en minuscules, éventuellement avec son schéma. Le rôle de l’application a besoin d’EXECUTE dessus. Prioritaire sur le corps ci-dessous.',
  'st.custom_body': 'Ou corps de fonction',
  'st.custom_body_help': 'PL/pgSQL avec p_username et p_password, qui renvoie true pour une connexion valide, p. ex. {example}',
  'st.custom_post': 'Code après authentification',
  'st.custom_post_help': 'PL/pgSQL facultatif exécuté après une vérification réussie, avec p_username (et meta.app_user()), p. ex. pour enregistrer la dernière connexion. Lever une exception refuse la connexion. Les processus d’application « after login » s’exécutent ensuite comme d’habitude.',
