  'st.session_group': 'Groupe de partage de session',
  'st.session_group_ph': 'vide : non partagée',
  'st.session_group_help': 'Les applications du même groupe (avec l’annuaire des utilisateurs comme authentification) partagent la connexion : après s’être connecté à l’une, les autres s’ouvrent sans nouvelle connexion, chacune avec son propre contrôle d’accès et ses rôles ; se déconnecter de l’une déconnecte de toutes (APEX : session sharing). Minuscules, chiffres et _.',
