  'rs.aria_valid_when': 'Valide si, pour {name}',
  'rs.aria_error_message': 'Message d\'erreur de {name}',
  'rs.col_validations_help': 'L\'expression doit être vraie pour une ligne ajoutée ou modifiée. Les colonnes de la ligne sont des variables de liaison portant leur nom en majuscules (:SAL, :COMM) ; les éléments de page et :APP_USER fonctionnent aussi. Une ligne qui échoue n\'est pas enregistrée et le message s\'affiche dans sa cellule.',
  'rs.the_visible_area_and_vector': 'La zone visible et les tuiles vectorielles nécessitent `lat`/`lng` (ou une géométrie PostGIS) et se rechargent quand la carte bouge. Les tuiles vectorielles dessinent points, lignes et zones, sans regroupement ni liste.',
  'rs.the_same_columns_as_the': 'Les mêmes colonnes que la requête de la carte. Videz la requête pour retirer la couche.',
  'rs.the_condition_runs_on_the': 'La condition s\'exécute sur le serveur : avec PostGIS installé sur une colonne geometry/geography, sinon sur la latitude et la longitude.',
  'rs.users_switch_between_the_ticked': 'Les utilisateurs basculent entre les vues cochées. Les heures hors plage sont ajoutées quand un événement en a besoin.',
  'rs.runs_as_the_application_s': 'S\'exécute avec le rôle de base de l\'application (la sécurité au niveau des lignes s\'applique) avec `:EVENT_ID` (la valeur de la colonne clé), `:NEW_START` et `:NEW_END` (même durée qu\'avant). Vide : les événements ne peuvent pas être déplacés.',
  'rs.only_events_the_user_sees': 'Seuls les événements que l\'utilisateur voit dans ce calendrier peuvent être déplacés ; sans souris, le lien de modification change les dates.',
  'rs.not_while_the_pointer_or': 'Pas tant que le pointeur ou le focus est dans le carrousel, ni pour les utilisateurs qui préfèrent les animations réduites. Un carrousel n\'a pas de « Tout afficher ».',
  'rs.a_chosen_region_gets_display': 'Une région choisie reçoit `"display_selector": true` dans ses paramètres (un onglet à son nom) ou le nom de l\'onglet : les régions de même nom d\'onglet partagent un onglet (p. ex. les filtres intelligents et leur rapport). Sans JavaScript, toutes les régions s\'affichent, avec des liens vers chacune.',
  'rs.gauge_charts_only_a_warning': 'Graphiques jauge uniquement. Un seuil d\'avertissement au-dessus du critique signifie que les valeurs basses sont mauvaises (p. ex. avertissement 50, critique 20).',
  'rs.drill_down_column_takes_the': 'Exploration : `#column#` prend la valeur de la ligne du point, `#series#` le nom de sa série. Les colonnes auxquelles seul le lien fait référence ne sont pas dessinées.',
  'rs.gantt_charts_with_a_task': 'Graphiques de Gantt avec une colonne `task_id`. S\'exécute avec le rôle de base de l\'application (la sécurité au niveau des lignes s\'applique) avec `:TASK_ID`, `:NEW_START` et `:NEW_END` (`YYYY-MM-DD`, ou `YYYY-MM-DDTHH:MM` à l\'heure ; un jalon reçoit le même début et la même fin). Vide : les tâches ne peuvent pas être déplacées.',
  'rs.only_tasks_the_user_sees': 'Seules les tâches que l\'utilisateur voit dans ce graphique peuvent être déplacées ; le graphique est ensuite redessiné à partir de sa requête.',
