  'rs.not_in_query': 'absente de la requête',
  'rpt.report_settings': 'Paramètres du rapport',
  'rpt.save_report_settings': 'Enregistrer les paramètres du rapport',
  'rs.no_position_alert': 'Le rapport n\'a pas de colonnes `lat`/`lng` ou `location` : la zone de carte ne peut donc pas le filtrer.',
  'rs.facets_help': 'Les cases à cocher listent les valeurs les plus fréquentes (Exclure permet plutôt de les écarter). Plages et De/à demandent une colonne numérique ou date : les plages sont `from..to = label` séparées par `;`, une borne ouverte laissée vide (`..1000`, `2020-01-01..`) ; une plage inclut son début, pas sa fin. Une note en étoiles propose « 4 étoiles et plus », etc. (jusqu\'à 5 ; `"max"` dans le JSON le change).',
  'rs.facets_help_chart': 'Graphique : un histogramme ou camembert des effectifs sous la facette (replié) ; une barre ou une part filtre sur sa valeur.',
  'rs.calendar_help': 'La requête renvoie `start_date`, `title` et éventuellement `end_date` (des dates pour les événements sur la journée, des horodatages pour ceux avec une heure).',
  'rs.chart_help': 'La première colonne est le libellé ; chaque colonne numérique suivante est une série (jusqu\'à 8). Un diagramme de Gantt lit `label, start, end` (dates ou horodatages ; une fin vide est un jalon) et des colonnes facultatives nommées `progress` (0 à 100), `task_id` et `depends_on` (les identifiants qu\'une tâche attend, par ex. `3,4`).',
  'rs.map_help': 'Chaque ligne est un marqueur en `lat`, `lng` (ou `location` sous la forme "lat,lng"), avec `title` et `body` dans sa bulle ; une colonne `geojson` trace des lignes et des surfaces (avec PostGIS installé, une colonne `geometry` ou `geography` en WGS 84 fonctionne aussi). Une carte de chaleur pondère chaque lieu par une colonne `weight`.',
  'rs.tree_help': 'La requête renvoie `id`, `parent_id` et `label` (et éventuellement `icon`) ; les lignes dont le parent n\'est pas dans le résultat sont les racines.',
  'rs.workflow_help': 'Les workflows viennent des définitions de workflow (Composants partagés) ; le SQL de l\'application les démarre avec `meta.start_workflow(…)`.',
  'rs.task_help': 'Les tâches viennent des définitions de tâche (Composants partagés) ; le SQL de l\'application les crée avec `meta.create_task(…)`.',
