  'rm.chk.runs_as': 'Les gestionnaires s\'exécutent en tant que `{role}`, avec `meta.app_user()` comme appelant',
  'rm.chk.role_problem': 'Le rôle de base de données de l\'application : {problem} Ses gestionnaires répondent 403.',
  'rm.chk.no_role': 'L\'application n\'a pas de rôle de base de données : les gestionnaires s\'exécutent avec le rôle d\'exécution de pgkiln. Donnez-lui son propre rôle (Application › Paramètres) pour que les droits et la sécurité au niveau des lignes soient les siens.',
  'rm.chk.disabled': 'Désactivé : chaque gestionnaire répond 404',
  'rm.chk.privilege': 'Privilège : les appelants doivent avoir le rôle {roles}',
  'rm.chk.no_privilege': 'Aucun rôle de privilège : tout jeton valide de l\'application (les gestionnaires peuvent ajouter des rôles)',
  'rm.response_as': '{request} en tant que {as}',
  'rm.try_intro': 'Envoie la requête au vrai point de terminaison : un PUT, POST ou DELETE modifie les données. {as} un compte émet pour lui un jeton de courte durée, comme le fait App › API REST ; sans compte, vous voyez ce qu\'obtient un appelant sans jeton.',
  'rm.intro': 'Modules des services RESTful : un module est un chemin de base d\'une application, ses modèles sont des URI avec des `:parameters`, et chaque modèle a des gestionnaires par méthode avec leur source : une requête de collection, une ligne unique, du SQL, un bloc PL/pgSQL ou une ressource média. Les gestionnaires s\'exécutent avec le rôle de base de données de l\'application et l\'appelant comme `meta.app_user()` : ses droits et la sécurité au niveau des lignes s\'appliquent ; les paramètres sont liés, jamais collés dans le SQL. Chaque module a un document OpenAPI. Les modules appartiennent à leur application : ils voyagent avec son export (aussi dans Composants partagés › Services RESTful).',
  'rm.source_help': 'Liaisons, en majuscules : paramètres de chemin ({params}), paramètres de requête et champs du corps JSON ; `:BODY` est le corps entier ; `:APP_USER` est l\'appelant. Les valeurs sont liées, jamais collées dans le SQL. PL/pgSQL : un bloc (`declare … begin … end`, ou des instructions) qui répond avec `perform meta.rest_reply(jsonb_build_object(…), 201)`. Média : une requête qui renvoie `content_type`, `content` et éventuellement `filename`.',
  'rm.params_help': 'Un par ligne : `name query|body|header [{types}] [required] [description]`. Ils vont dans le document OpenAPI et le formulaire Essayer ; s\'il en manque un obligatoire, la réponse est 400. Un paramètre d\'en-tête lit l\'en-tête de la requête portant son nom, avec - à la place de _ (`x_request_id` lit `X-Request-Id`).',
  'rm.e.params_line': 'Paramètres, ligne {n} : écrivez "name query", "name body" ou "name header", puis éventuellement un type ({types}), "required" et une description.',
  'rm.e.choose_app': 'Choisissez une application de cet espace de travail.',
  'rm.e.base_path': 'Le chemin de base commence par une lettre minuscule : lettres, chiffres, _ et - (40 au plus).',
