  'ar.intro': 'Services RESTful : publiez une table ou une vue comme points de terminaison REST (AutoREST). Les lignes arrivent paginées en JSON, avec des filtres ; une clé primaire permet GET, PUT et DELETE d\'une ligne. Les requêtes s\'exécutent avec le rôle de base de données de l\'application qui publie et l\'appelant comme `meta.app_user()` : ses droits et la sécurité au niveau des lignes s\'appliquent.',
