  'wres.servers_intro': 'URL de base nommées de {workspace} : une source de données REST, un catalogue de sources REST ou un service IA désigne un serveur et un chemin au lieu d\'une URL complète, donc passer du développement à la production change une valeur ici (ou une variable d\'environnement) et toutes les sources du serveur suivent aussitôt. L\'URL passe toujours toutes les vérifications d\'une URL complète : la liste autorisée de l\'installation, la liste {network} de cet espace de travail et les vérifications d\'adresse lors de l\'appel.',
