  'wres.files_intro': 'CSS, JavaScript, JSON, images et polices que toute application de {workspace} peut utiliser : une application en charge un sur chaque page avec {tag} dans Composants partagés → Fichiers statiques d\'application → Chaque page charge (une page : Page → Apparence), et les modèles, le HTML et les liens utilisent {sub} pour leur URL. Chaque application les sert depuis sa propre adresse ({path}), jamais ceux d\'un autre espace de travail. Jusqu\'à {size} par fichier ; pas de HTML. Ils voyagent avec l\'export de l\'espace de travail.',
  'wres.type_help': 'basic : nom d\'utilisateur + mot de passe · header : un en-tête HTTP avec le secret (clé d\'API) · bearer : Authorization: Bearer <secret> · oauth2 : octroi client credentials, mot de passe ou jeton d\'actualisation · aws_sigv4 : un stockage d\'objets compatible S3.',
  'wres.credentials_intro': 'Identifiants web de {workspace} que ses applications utilisent par leur nom dans les sources de données REST, le processus Appeler une API, les serveurs distants et le stockage d\'objets, si bien qu\'une clé est saisie une seule fois pour l\'espace de travail. L\'identifiant propre d\'une application (Composants partagés → Identifiants web) de même nom l\'emporte. Les secrets sont chiffrés avec la clé du serveur, jamais réaffichés ni exportés.',
