  'asst.run_before_each_question_their': 'Exécutées avant chaque question ; leurs lignes vont au modèle comme données. `[{"name": "policy", "sql": "select title, body from hr.policy where body @@ plainto_tsquery(:AI_PROMPT)", "max_rows": 5}]` (`:AI_PROMPT` est la question, `:APP_USER` et les éléments comme d\'habitude).',
  'asst.the_model_calls_them_when': 'Le modèle les appelle quand il en a besoin. SQL : `{"name": "my_leave", "description": "…", "sql": "select … where status = :STATUS", "parameters": {"STATUS": {"type": "string", "enum": ["PENDING", "APPROVED"]}}}` ; ajoutez `"writes": true` pour un outil qui modifie des données et `"authz": "SCHEME"` pour ne le proposer qu\'à certains utilisateurs. REST : `{"name": "department", "type": "rest", "source": "DEPARTMENT", "description": "…", "parameters": {"dname": {"type": "string"}}}`. Types de paramètres : string, integer, number, boolean, date ; `"optional": true` permet de n\'en donner aucun.',
  'asst.agent_help': 'Un agent de {link} définit le service, le prompt système, l\'effort de raisonnement, les outils et les étapes ; enregistrer avec un agent retire le service, le prompt système, les outils et les tours d\'outils propres à la région.',
