  'agt.intro': 'Un agent répond dans une région d\'assistant IA et n\'agit qu\'au moyen des outils que vous lui donnez : requêtes SQL (lecture seule, avec le rôle de base de données de l\'application, donc la sécurité au niveau des lignes s\'applique), fonctions PL/pgSQL, sources de données REST, actions JavaScript dans le navigateur et liens vers des pages (pgkiln construit l\'URL et sa somme de contrôle, seulement pour les pages que l\'utilisateur peut ouvrir). Un outil Retrieve donne à l\'agent les lignes d\'une configuration de recherche qui correspondent à un texte par le sens (RAG), toujours avec le rôle de l\'application. Ce que tapent les utilisateurs et les résultats des outils vont au service IA de l\'agent. {usage} liste chaque appel d\'outil.',
